tool_input.command:
cat > "C:/Users/User1/AppData/Local/Temp/claude/C--Users-User1-Desktop-dark-raiders/8a09e991-b4f4-4b23-b10f-ded92e837fc3/scratchpad/mk-cw-uc-rewbar.ps1" <<'EOF'
$g=[IO.File]::ReadAllText($(if($env:MK_SRC){$env:MK_SRC}else{'C:\claudecode\dark raiders\dark_raiders.html'}))
function L([string]$rx){ $m=[regex]::Matches($g,$rx); if($m.Count -ne 1){ throw "anchor $rx matched $($m.Count)" }; return $m[0].Value.Replace("`r",'') }
$a1=L '#root #termsmodal #termsclear\{ min-width:200px; min-height:48px; font-size:18px; \}[^\r\n]*'
$css=@'

/* v28.xx (cw-uc-rewbar) b-31 step 7, critic on 13 rewards (2: no hierarchy, intro sentence, 13px bar, dead right column) and 16 bar (2: two lime buttons, flavour line, duplicate money line): rewards intro hidden, xp label 24px, bar 28px with 16px count, list 1400px wide with 64px rows; bar and craft lose the duplicate "you hold" line, the bar loses its flavour line, ingest buttons are ghost until hovered or focused, prices light instead of lime. */
#root #opane_rew{ max-width:1400px; }
#root #opane_rew > .msub:not(#roadmaphead){ display:none !important; }
#root #seasonhead{ font-size:24px !important; font-weight:800; letter-spacing:.08em !important; color:#e8e2d4 !important; padding-bottom:4px !important; }
#root #seasonbar{ height:28px !important; }
#root #seasontext{ font-size:16px !important; line-height:28px !important; }
#root #seasonclaimall{ width:auto !important; padding:10px 28px !important; align-self:flex-end; }
#root #seasonlist .row{ min-height:64px; font-size:20px; }
#root #seasonlist .row .vl{ color:var(--ash); }
#root #wallet_work, #root #wallet_merc, #root #wallet_bar, #root #bar_line{ display:none !important; }
#root #barmodal .row .hint{ font-size:16px; }
#root #barmodal .row .vl{ color:#e8e2d4; }
#root #barmodal .row button:not(:disabled):not(:hover):not(:focus){ background:transparent; color:#e6ff3d; border:1px solid #e6ff3d; }
'@.Replace("`r",'')
$r1=$a1+$css.TrimEnd("`n")
$chk=@'
  {v:'VER',what:'rewards intro hidden and bar 28px, bar flavour and wallet lines hidden, ingest ghost when idle',
   run:function(){
     var bad=[];
     try{
       var rw=document.getElementById('opane_rew'), m=rw.querySelector(':scope > .msub:not(#roadmaphead)');
       if(m&&getComputedStyle(m).display!=='none') bad.push('rewards intro shows');
       if(getComputedStyle(document.getElementById('seasonbar')).height!=='28px') bad.push('bar h '+getComputedStyle(document.getElementById('seasonbar')).height);
       if(getComputedStyle(rw).maxWidth!=='1400px') bad.push('rew maxw '+getComputedStyle(rw).maxWidth);
       if(getComputedStyle(document.getElementById('bar_line')).display!=='none') bad.push('bar_line shows');
       if(getComputedStyle(document.getElementById('wallet_bar')).display!=='none') bad.push('wallet_bar shows');
       renderBar();
       var bt=document.querySelector('#barlist [data-bz]');
       if(bt&&!bt.disabled){ var bg=getComputedStyle(bt).backgroundColor; if(bg!=='rgba(0, 0, 0, 0)') bad.push('ingest filled '+bg); }
     }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
     return bad.length?bad.join('; '):null; }},
'@.Replace("`r",'')
$d=[ordered]@{
  title='Rewards and bar: one focus, fewer lines'
  why='UI step 7 (restyle only). Critic on 13 and 16 was 2: no hierarchy, explaining and flavour lines, two competing lime buttons. Lines hidden under Q8 (logged in changes.md).'
  now='The rewards page loses its intro and gets a bigger bar; the bar page loses two lines and its buttons go ghost until selected.'
  edits=@( [ordered]@{ anchor=$a1; replacement=$r1 } )
  check=$chk
}
[IO.File]::WriteAllText('C:\claudecode\dark raiders\tools\handoff\drafts\draft-cw-uc-rewbar.json',($d | ConvertTo-Json -Depth 6),(New-Object Text.UTF8Encoding $false))
'written'
EOF
